<section class="admin-card admin-category-manager-card">
    <div class="admin-toolbar"><div><h2>Categories</h2><p class="admin-muted">Paused categories stay available in admin but are hidden from the public menu.</p></div><span class="admin-muted"><?php echo $categoryCounts['all']; ?> categories</span></div>
    <form method="post" class="admin-form admin-category-form" data-inline-validate>
        <input type="hidden" name="csrf" value="<?php echo adminEscape(adminToken()); ?>">
        <input type="hidden" name="category_id" value="<?php echo (int) ($editingCategory['category_id'] ?? 0); ?>">
        <label for="category-name"><?php echo $editingCategory ? 'Edit category' : 'New category'; ?><input id="category-name" name="category_name" maxlength="50" value="<?php echo adminEscape($_POST['category_name'] ?? $editingCategory['name'] ?? ''); ?>" required aria-describedby="category-error"><small id="category-error" class="field-error" aria-live="polite"><?php echo adminEscape($categoryError); ?></small></label>
        <button class="admin-btn" type="submit" name="<?php echo $editingCategory ? 'update_category' : 'add_category'; ?>"><i class="bi <?php echo $editingCategory ? 'bi-floppy' : 'bi-plus-lg'; ?>" aria-hidden="true"></i> <?php echo $editingCategory ? 'Save category' : 'Add category'; ?></button>
        <?php if ($editingCategory) { ?><a class="admin-btn secondary" href="menu.php?tab=categories&amp;status=<?php echo adminEscape($categoryStatus); ?>">Cancel</a><?php } ?>
    </form>
    <nav class="admin-category-status-tabs" aria-label="Category status">
        <?php foreach (array('all'=>'All', 'active'=>'Active', 'inactive'=>'Inactive') as $status => $label) { ?><a href="menu.php?tab=categories&amp;status=<?php echo $status; ?>"<?php echo $categoryStatus === $status ? ' aria-current="page"' : ''; ?>><?php echo $label; ?><span><?php echo $categoryCounts[$status]; ?></span></a><?php } ?>
    </nav>
    <div class="admin-list-tools admin-category-tools"><label><i class="bi bi-search" aria-hidden="true"></i><input id="category-search" type="search" placeholder="Search <?php echo $categoryStatus === 'all' ? 'categories' : $categoryStatus . ' categories'; ?>" autocomplete="off"></label><button type="button" class="admin-btn secondary" id="category-search-reset" hidden><i class="bi bi-arrow-counterclockwise" aria-hidden="true"></i> Reset</button></div>
    <div class="admin-category-records" id="admin-category-list">
        <?php foreach ($visibleCategories as $category) { ?><article data-category-status="<?php echo $category['is_active'] ? 'active' : 'inactive'; ?>"><div class="admin-category-record-main"><strong><?php echo adminEscape($category['name']); ?></strong><span class="admin-category-badge <?php echo $category['is_active'] ? 'is-active' : 'is-inactive'; ?>"><?php echo $category['is_active'] ? 'Active' : 'Paused'; ?></span></div><div class="admin-category-record-actions"><form method="post" class="admin-inline"><input type="hidden" name="csrf" value="<?php echo adminEscape(adminToken()); ?>"><input type="hidden" name="category_id" value="<?php echo (int) $category['category_id']; ?>"><button class="admin-status-toggle <?php echo $category['is_active'] ? 'is-active' : ''; ?>" type="submit" name="toggle_category_status" title="<?php echo $category['is_active'] ? 'Pause category' : 'Activate category'; ?>"><i class="bi <?php echo $category['is_active'] ? 'bi-toggle-on' : 'bi-toggle-off'; ?>" aria-hidden="true"></i><?php echo $category['is_active'] ? 'Active' : 'Paused'; ?></button></form><a href="menu.php?tab=categories&amp;status=<?php echo adminEscape($categoryStatus); ?>&amp;edit_category=<?php echo (int) $category['category_id']; ?>" class="admin-icon-button" aria-label="Edit <?php echo adminEscape($category['name']); ?>" title="Edit category"><i class="bi bi-pencil-square" aria-hidden="true"></i></a><form method="post" class="admin-inline" onsubmit="return confirm('Delete <?php echo adminEscape($category['name']); ?>? This only works when nothing uses it.')"><input type="hidden" name="csrf" value="<?php echo adminEscape(adminToken()); ?>"><input type="hidden" name="category_id" value="<?php echo (int) $category['category_id']; ?>"><button type="submit" name="delete_category" class="admin-icon-button danger" aria-label="Delete <?php echo adminEscape($category['name']); ?>" title="Delete category"><i class="bi bi-trash" aria-hidden="true"></i></button></form></div></article><?php } ?>
    </div>
    <p class="admin-category-empty" id="category-search-empty"<?php echo $visibleCategories ? ' hidden' : ''; ?>><i class="bi bi-search" aria-hidden="true"></i> No <?php echo $categoryStatus === 'all' ? '' : $categoryStatus . ' '; ?>categories match that search.</p>
</section>
<script>(function(){const search=document.getElementById('category-search'),reset=document.getElementById('category-search-reset'),cards=Array.from(document.querySelectorAll('#admin-category-list article')),empty=document.getElementById('category-search-empty');if(!search||!reset||!empty)return;function filter(){const query=search.value.trim().toLowerCase();let matches=0;cards.forEach(function(card){const show=card.textContent.toLowerCase().includes(query);card.hidden=!show;if(show)matches++;});reset.hidden=query==='';empty.hidden=matches>0;}search.addEventListener('input',filter);reset.addEventListener('click',function(){search.value='';filter();search.focus();});}());</script>
